@startuml

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Employee {
  + ssn : string
  + name : string
  + email : string
}

class ResearchAssistant extends Employee {
  + fieldOfResearch : string
}

class Lecturer extends ResearchAssistant {}

class Project {
  + name : string
  + startDate : date
  + endDate : date
  + hours : int
}

class Course {
  + id : int
  + name : string
  + weeklyDuration : int
}

Faculty "1" -- "*" Institute : made up of
Faculty "1" -- "1" Employee : headed by
Institute "1" -- "*" ResearchAssistant : has
ResearchAssistant "1" -- "*" Project : involved in
Lecturer "1" -- "*" Course : teaches

@enduml

